from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    X = int(input[1])
    D = int(input[2])

    if D == 0:
        if X == 0:
            print(1)
        else:
            print(N + 1)
        return

    D_abs = abs(D)
    intervals = defaultdict(list)

    for m in range(N + 1):
        min_s = m * (m - 1) // 2
        max_s = m * (2 * N - m - 1) // 2

        if D >= 0:
            low_m = m * X + D * min_s
            high_m = m * X + D * max_s
        else:
            low_m = m * X + D * max_s
            high_m = m * X + D * min_s

        r_m = (m * X) % D_abs
        intervals[r_m].append( (low_m, high_m) )

    total = 0
    for r in intervals:
        sorted_intervals = sorted(intervals[r], key=lambda x: x[0])
        merged = []
        for start, end in sorted_intervals:
            if not merged:
                merged.append( [start, end] )
            else:
                last_start, last_end = merged[-1]
                if start <= last_end:
                    new_start = last_start
                    new_end = max(last_end, end)
                    merged[-1] = [new_start, new_end]
                else:
                    merged.append( [start, end] )
        for start, end in merged:
            count = ((end - start) // D_abs) + 1
            total += count

    print(total)

if __name__ == "__main__":
