    dp_max[0] = 0
    for n in range(1, N + 1):
        for d in allowed_digits:
            c = cost[d]
            if c <= n and dp_max[n - c] != -1:
                if dp_max[n] < dp_max[n - c] + 1:
                    dp_max[n] = dp_max[n - c] + 1
    K = dp_max[N]

    def build(n, k):
        if k == 0:
            return ''
        for d in allowed_digits:
            c = cost[d]
            if n >= c and dp_max[n - c] == k - 1:
                return str(d) + build(n - c, k - 1)
        return ''

    result = build(N, K)
    print(result)

