            if c <= i:
                if dp[i - c] + 1 > dp[i]:
                    dp[i] = dp[i - c] + 1
    current_max = dp[n]
    remaining = n
    res = []
    for _ in range(current_max):
        for d in range(9, 0, -1):
            if d in allowed_set:
                c = cost[d]
                if remaining >= c and dp[remaining - c] == current_max - 1:
                    res.append(str(d))
                    remaining -= c
                    current_max -= 1
                    break
    print(''.join(res))

