import sys

def factorize(x):
    factors = {}
    i = 2
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x = x // i
        i += 1
    if x > 1:
        factors[x] = 1
    return factors

def get_divisors(x):
    if x == 0:
        return []
    factors = factorize(x)
    divisors = [1]
    for prime, exp in factors.items():
        current_length = len(divisors)
        prime_powers = [prime**i for i in range(1, exp+1)]
        for power in prime_powers:
            for i in range(current_length):
                divisors.append(divisors[i] * power)
    return divisors

def main():
    N = int(sys.stdin.readline())
    # Case 1: divisors of N-1 >=2
    case1 = []
    if N - 1 >= 1:
        divisors_case1 = get_divisors(N - 1)
        case1 = [d for d in divisors_case1 if d >= 2]
    # Case 2: divisors of N >=2, check condition
    divisors_case2 = get_divisors(N)
    count_case2 = 0
    for d in divisors_case2:
        if d < 2:
            continue
        temp = N
        while temp % d == 0:
            temp //= d
        if temp % d == 1:
            count_case2 += 1
    total = len(case1) + count_case2
    print(total)

if __name__ == '__main__':
    main()
