import sys
from functools import lru_cache

def main():
    N, K = map(int, sys.stdin.readline().split())
    A = list(map(int, sys.stdin.readline().split()))

    max_bit = 40  # since K can be up to 1e12, which is about 40 bits
    cnt = [0] * (max_bit + 1)
    for j in range(max_bit + 1):
        for a in A:
            cnt[j] += (a >> j) & 1

    @lru_cache(maxsize=None)
    def dfs(bit, tight):
        if bit < 0:
            return 0
        max_sum = 0
        if tight:
            current_k_bit = (K >> bit) & 1
            for b in [0, 1]:
                if b > current_k_bit:
                    continue
                new_tight = tight and (b == current_k_bit)
                if b == 0:
                    contribution = cnt[bit] * (1 << bit)
                else:
                    contribution = (N - cnt[bit]) * (1 << bit)
                res = contribution + dfs(bit - 1, new_tight)
                if res > max_sum:
                    max_sum = res
        else:
            for b in [0, 1]:
                if b == 0:
                    contribution = cnt[bit] * (1 << bit)
                else:
                    contribution = (N - cnt[bit]) * (1 << bit)
                res = contribution + dfs(bit - 1, False)
                if res > max_sum:
                    max_sum = res
        return max_sum

    result = dfs(max_bit, True)
    print(result)

if __name__ == "__main__":
