import sys
import collections

def main():
    N, K = map(int, sys.stdin.readline().split())
    H = list(map(int, sys.stdin.readline().split()))

    INF = float('inf')

    # dp[i][k] is a dictionary: {prev_value: min_sum}
    dp = [ [collections.defaultdict(lambda: INF) for _ in range(K+1)] for _ in range(N) ]

    # Initialize first column
    for k in range(K+1):
        # case 1: current value is original H[0]
        if k == 0:
            dp[0][k][H[0]] = H[0]
        # case 2: current value is 0 (changed)
        if k >= 1:
            dp[0][k][0] = 0

    for i in range(1, N):
        for k in range(K+1):
            # Iterate over all possible previous values and previous k values
            for prev_k in range(k+1):
                for prev_val in dp[i-1][prev_k]:
                    # Current value can be H[i] (no change) or prev_val (change)
                    # Case 1: current value is H[i]
                    if prev_k <= k:
                        # No change needed
                        new_sum = dp[i-1][prev_k][prev_val] + max(0, H[i] - prev_val)
                        if new_sum < dp[i][k][H[i]]:
                            dp[i][k][H[i]] = new_sum
                    # Case 2: current value is prev_val (change needed if H[i] != prev_val)
                    if prev_k + 1 <= k:
                        # Change needed
                        new_sum = dp[i-1][prev_k][prev_val] + max(0, prev_val - prev_val)
                        if new_sum < dp[i][k][prev_val]:
                            dp[i][k][prev_val] = new_sum

    # Find the minimum value in the last column for all k <= K
    result = INF
    for k in range(K+1):
        for val in dp[N-1][k]:
            if dp[N-1][k][val] < result:
                result = dp[N-1][k][val]
    print(result)

if __name__ == "__main__":
    main()
