from collections import deque

def main():
    N, u, v = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        a, b = map(int, sys.stdin.readline().split())
        adj[a].append(b)
        adj[b].append(a)

    def bfs(start):
        dist = [-1] * (N + 1)
        q = deque()
        dist[start] = 0
        q.append(start)
        while q:
            current = q.popleft()
            for neighbor in adj[current]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[current] + 1
                    q.append(neighbor)
        return dist

    dist_u = bfs(u)
    dist_v = bfs(v)

    max_dist = 0
    for x in range(1, N + 1):
        if dist_u[x] < dist_v[x]:
            if dist_v[x] > max_dist:
                max_dist = dist_v[x]

    print(max_dist - 1)

