    def sieve(n):
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(n**0.5) + 1):
            if is_prime[i]:
                for j in range(i*i, n+1, i):
                    is_prime[j] = False
        primes = [i for i, val in enumerate(is_prime) if val]
        return primes

    primes = sieve(N)
    k = len(primes)

    # Calculate exponents of each prime in N!
    def legendre(n, p):
        count = 0
        while n > 0:
            n //= p
            count += n
        return count

    exponents = [legendre(N, p) for p in primes]

    # Generate all divisors of 75
    divisors = [1, 3, 5, 15, 25, 75]

    # Generate all possible tuples of length k with product 75
    results = []
    def generate_tuples(product, length, current, results):
        if length == 0:
            if product == 1:
                results.append(current)
            return
        for d in divisors:
            if product % d == 0:
                generate_tuples(product // d, length - 1, current + [d], results)

    generate_tuples(75, k, [], results)

    total = 0

    for tuple in results:
        used = [False] * k
        count = 0

        def backtrack(pos, current_product):
            nonlocal count
            if pos == k:
                if current_product == 75:
                    count += 1
                return
            for i in range(k):
                if not used[i]:
                    if tuple[pos] <= exponents[i] + 1:
                        used[i] = True
                        backtrack(pos + 1, current_product * tuple[pos])
                        used[i] = False

        backtrack(0, 1)
        total += count

    print(total)

