import sys
import math

def sieve(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.sqrt(n)) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    primes = [i for i, val in enumerate(is_prime) if val]
    return primes

def get_exponent(n, p):
    count = 0
    while n >= p:
        n = n // p
        count += 1
    return count

def get_divisors(m):
    divisors = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.add(i)
            divisors.add(m // i)
    return list(divisors)

def main():
    N = int(sys.stdin.readline())
    primes = sieve(N)
    exponents = [get_exponent(N, p) for p in primes]
    count = 0

    def backtrack(index, remaining):
        nonlocal count
        if index == len(primes):
            if remaining == 1:
                count += 1
            return
        for d in get_divisors(remaining):
            if d <= (exponents[index] + 1):
                backtrack(index + 1, remaining // d)

    backtrack(0, 75)
    print(count)

if __name__ == "__main__":
    main()
