    def sum_m2(a, b):
        return (b * (b + 1) * (2 * b + 1) // 6) - ((a - 1) * a * (2 * (a - 1) - 1) // 6)

    sum_m_val = sum_m(K, M)
    sum_m2_val = sum_m2(K, M)

    term1 = (M * sum_m_val - sum_m2_val) % MOD
    term2 = (M - K + 1) % MOD

    total = (term1 + term2) % MOD
    print(total)

